#!/usr/bin/env node
/**
 * Generate design-token outputs from src/design/tokens.json:
 *   src/design/tokens.css           CSS custom properties (--td-*)
 *   src/design/theme.js             ES module for canvas/SVG charts and figures
 *   src/design/tailwind-preset.cjs  Tailwind preset for the website
 *   src/design/contrast-report.json WCAG contrast of every documented pairing
 * `--check` fails if generated files are stale or a pairing is below its threshold.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'design');
const tokens = JSON.parse(readFileSync(join(root, 'tokens.json'), 'utf8'));
const check = process.argv.includes('--check');

const kebab = (s) => s.replace(/\./g, '_');
const hexToRgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
const rgba = (hex, a) => `rgba(${hexToRgb(hex).join(', ')}, ${a})`;
const colorValue = (t) => (t.alpha !== undefined ? rgba(t.value, t.alpha) : t.value);

function luminance(hex) {
  const [r, g, b] = hexToRgb(hex).map((v) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
export function contrast(a, b) {
  const [l1, l2] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
}

const c = tokens.color;
const flat = {};
for (const [group, entries] of Object.entries(c)) {
  if (entries.value) { flat[group] = colorValue(entries); continue; }
  for (const [name, t] of Object.entries(entries)) flat[`${group}-${name}`] = colorValue(t);
}

// ---------- CSS ----------
const lines = [`/* Generated by tools/build-tokens.mjs from tokens.json v${tokens.meta.version}. Do not edit. */`, ':root {'];
for (const [k, v] of Object.entries(flat)) lines.push(`  --td-color-${k}: ${v};`);
for (const [k, t] of Object.entries(tokens.font)) lines.push(`  --td-font-${k}: ${t.value};`);
for (const [k, v] of Object.entries(tokens.size.text)) lines.push(`  --td-text-${kebab(k)}: ${v}px;`);
for (const [k, v] of Object.entries(tokens.size.space)) lines.push(`  --td-space-${kebab(k)}: ${v}px;`);
lines.push(`  --td-control-height: ${tokens.size['control-height']}px;`, `  --td-touch-target: ${tokens.size['touch-target']}px;`, `  --td-rule: ${tokens.size.rule}px;`, `  --td-focus-ring: ${tokens.size['focus-ring']}px;`);
for (const [k, v] of Object.entries(tokens.radius)) lines.push(`  --td-radius-${k}: ${v}px;`);
for (const [k, v] of Object.entries(tokens.shadow)) lines.push(`  --td-shadow-${k}: ${v};`);
for (const k of ['fast', 'base', 'slow', 'ease']) lines.push(`  --td-motion-${k}: ${tokens.motion[k]};`);
lines.push('}', '@media (prefers-reduced-motion: reduce) {', '  :root { --td-motion-fast: 0ms; --td-motion-base: 0ms; --td-motion-slow: 0ms; }', '}', '');
const css = lines.join('\n');

// ---------- JS theme ----------
const theme = {
  version: tokens.meta.version,
  color: Object.fromEntries(Object.entries(c).map(([g, e]) => [g, e.value ? e.value : Object.fromEntries(Object.entries(e).map(([n, t]) => [n, colorValue(t)]))])),
  font: Object.fromEntries(Object.entries(tokens.font).map(([k, t]) => [k, t.value])),
  text: tokens.size.text,
  space: tokens.size.space,
  shadow: tokens.shadow,
  chart: tokens.chart,
  statusIcon: Object.fromEntries(Object.entries(c.status).map(([k, t]) => [k, t.icon])),
};
const js = `/* Generated by tools/build-tokens.mjs from tokens.json v${tokens.meta.version}. Do not edit. */\nexport const theme = Object.freeze(${JSON.stringify(theme, null, 2)});\nexport default theme;\n`;

// ---------- Tailwind preset ----------
const tw = {
  theme: {
    extend: {
      colors: {
        td: Object.fromEntries(Object.entries(flat).map(([k]) => [k, `var(--td-color-${k})`])),
      },
      fontFamily: { editorial: tokens.font.editorial.value.split(',').map((s) => s.trim().replace(/'/g, '')), instrument: tokens.font.ui.value.split(',').map((s) => s.trim().replace(/'/g, '')) },
      boxShadow: { 'td-hard': tokens.shadow.hard },
    },
  },
};
const preset = `/* Generated by tools/build-tokens.mjs from tokens.json v${tokens.meta.version}. Do not edit. */\nmodule.exports = ${JSON.stringify(tw, null, 2)};\n`;

// ---------- contrast ----------
const bg = [c.surface.base.value, c.surface.panel.value];
const pairs = [];
const add = (name, fg, back, min) => pairs.push({ name, fg, bg: back, ratio: Number(contrast(fg, back).toFixed(2)), min, pass: contrast(fg, back) >= min });
for (const b of bg) {
  add(`ink-primary on ${b}`, c.ink.primary.value, b, 4.5);
  add(`ink-muted on ${b}`, c.ink.muted.value, b, 4.5);
  for (const [k, t] of Object.entries(c.data)) if (t.alpha === undefined) add(`data-${k} on ${b} (graphics)`, t.value, b, 3);
  for (const [k, t] of Object.entries(c.status)) add(`status-${k} on ${b} (text)`, t.value, b, 4.5);
  // Also used as text: links (periwinkle), key numbers (rose), kickers and numerals (brass).
  for (const k of ['rose', 'periwinkle']) add(`data-${k} on ${b} (text)`, c.data[k].value, b, 4.5);
  add(`brand-brass on ${b} (text)`, c.brand.brass.value, b, 4.5);
}
add('white on brand-red', c.brand.white.value, c.brand.red.value, 4.5);
add('inverse on brand-red-light', c.ink.inverse.value, c.brand['red-light'].value, 4.5);
add('inverse on offwhite', c.ink.inverse.value, c.brand.offwhite.value, 4.5);
add('inverse on ivory (photo mats)', c.ink.inverse.value, c.brand.ivory.value, 4.5);
add('focus ring on base (UI component)', c.focus.value, c.surface.base.value, 3);
add('brand-red on base (NOT for text or lines)', c.brand.red.value, c.surface.base.value, 0);
const report = { generated_from: `tokens.json v${tokens.meta.version}`, pairs };
const reportJson = JSON.stringify(report, null, 2) + '\n';

const outputs = { 'tokens.css': css, 'theme.js': js, 'tailwind-preset.cjs': preset, 'contrast-report.json': reportJson };
let stale = false;
for (const [file, content] of Object.entries(outputs)) {
  const path = join(root, file);
  if (check) {
    let current = '';
    try { current = readFileSync(path, 'utf8'); } catch { /* missing */ }
    if (current !== content) { stale = true; console.error(`stale: ${file} (run npm run tokens)`); }
  } else writeFileSync(path, content);
}
const failing = pairs.filter((p) => !p.pass);
for (const p of failing) console.error(`contrast below ${p.min}: ${p.name} = ${p.ratio}`);
console.log(`${check ? 'checked' : 'wrote'} design tokens; ${pairs.length - failing.length}/${pairs.length} contrast pairings pass`);
process.exit(stale || failing.length ? 1 : 0);
